/*getBuyerShoppingCartOrderListConfirmList2*/
SELECT ROWNUM No, --00 Z.IMGFILE_NAME, --01 Z.IMGFILE_DIR, --02 Z.BUYER_ITEM_NO, --03 Z.DESCRIPTION_LOC, --04 Z.SPECIFICATION, --05 Z.ORIGIN_NAME, --06 Z.MAKER_NAME, --07 Z.UNIT_MEASURE, --08 Z.TARGET_PRICE, --09 Z.CATEGORY_NO, --10 DECODE(NVL(Z.AGENT,'MULTI'),'MULTI','복수협력사입니다',Z.AGENT) AGENT, --11 Z.CART_QTY, --12 Z.TOT_SUM, --13 Z.STDCATEG_ID, --14 Z.CONTRACT_NO, --15 Z.CONTRACT_SEQ, --16 Z.BYIT_COMORG_CODE, --17 Z.REF_PR_NO, --18 Z.AGENT_CODE, --19 Z.BDGT_FLAG, --20 Z.ACCOUNT_TYPE --21 , Z.HI_DEPT_CODE --22 , Z.HI_DEPT_NAME --23 , Z.IMAGE_KEY , Z.CATE_APPR --25.카테고리별결재담당자 , Z.MG_NOTE , Z.CART_SEQ , Z.DELY_TO_LOCATION_TEXT , Z.RECV_USER_NAME , Z.RECV_USER_TEL , Z.CART_ACCOUNT_TYPE , F_GET_WORKINGDAY(TO_CHAR(SYSDATE, 'YYYYMMDD'), Z.DELIVERY_LT) AS DS_LT -- 표준납기일 , Z.DELIVERY_LT -- 납기 리드타임 FROM (SELECT ROWNUM NUM, Y.IMGFILE_NAME, Y.IMGFILE_DIR, Y.BUYER_ITEM_NO, Y.DESCRIPTION_LOC, Y.SPECIFICATION, Y.ORIGIN_NAME, Y.MAKER_NAME, Y.UNIT_MEASURE, Y.TARGET_PRICE, Y.CATEGORY_NO, Y.AGENT, Y.CART_QTY, Y.TOT_SUM, Y.STDCATEG_ID, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.BYIT_COMORG_CODE, Y.REF_PR_NO, Y.AGENT_CODE, Y.BDGT_FLAG, Y.ACCOUNT_TYPE, Y.HI_DEPT_CODE, Y.HI_DEPT_NAME, Y.IMAGE_KEY, Y.CATE_APPR, Y.MG_NOTE, Y.CART_SEQ, Y.DELY_TO_LOCATION_TEXT, Y.RECV_USER_NAME, Y.RECV_USER_TEL, Y.CART_ACCOUNT_TYPE, Y.DELIVERY_LT FROM (SELECT X.IMGFILE_NAME, X.IMGFILE_DIR, MAX(X.BUYER_ITEM_NO) BUYER_ITEM_NO, X.DESCRIPTION_LOC, X.SPECIFICATION, X.ORIGIN_NAME, X.MAKER_NAME, X.UNIT_MEASURE, X.TARGET_PRICE, X.CATEGORY_NO, P.COM_NAME_LOC AGENT, X.CART_QTY, X.TOT_SUM, X.STDCATEG_ID, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BYIT_COMORG_CODE, X.REF_PR_NO, X.AGENT AGENT_CODE, X.BDGT_FLAG, X.ACCOUNT_TYPE, MAX(X.HI_DEPT_CODE) AS HI_DEPT_CODE, MAX(X.HI_DEPT_NAME) AS HI_DEPT_NAME, X.IMAGE_KEY, X.CATE_APPR, X.MG_NOTE, X.SEQ CART_SEQ, X.DELY_TO_LOCATION_TEXT, X.RECV_USER_NAME, X.RECV_USER_TEL, X.CART_ACCOUNT_TYPE, X.DELIVERY_LT FROM ( SELECT DECODE(TRIM(B.IMGFILE_NAME), NULL, (SELECT IMG_NAME FROM CMSIMGES WHERE IMG_NO=D.IMG_NO),B.IMGFILE_NAME) AS IMGFILE_NAME, DECODE(TRIM(B.IMGFILE_DIR), NULL, (SELECT IMG_DIR FROM CMSIMGES WHERE IMG_NO=D.IMG_NO),B.IMGFILE_DIR) AS IMGFILE_DIR, C.BUYER_ITEM_NO, C.DESCRIPTION DESCRIPTION_LOC, C.SPECIFICATION, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE) ORIGIN_NAME, C.MAKER_NAME, C.UNIT_MEASURE, DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) TARGET_PRICE, B.CATEGORY_NO, DECODE(CM.AGENT_OPEN_FLAG,'Y',C.AGENT,'KRKORE0001') AGENT, DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) CART_QTY, (DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) ) TOT_SUM, B.STDCATEG_ID, C.CONTRACT_NO, C.CONTRACT_SEQ, A.BYIT_COMORG_CODE, A.REF_PR_NO, (SELECT Z.FLAG FROM ICOMCOD2 Z WHERE Z.TYPE = 'Z014' AND Z.COMPANY_CODE = A.BUYER AND Z.CODE = DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE,A.ACCOUNT_TYPE) ) BDGT_FLAG, B.ACCOUNT_TYPE ACCOUNT_TYPE , A.HI_DEPT_CODE , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.HI_DEPT_CODE AND TYPE = 'U001' AND FLAG = 'Y') AS HI_DEPT_NAME , A.VERIF_NUM AS VERIF_NUM , A.IMAGE_KEY , (SELECT COUNT(*) FROM ICOMCOD3 CT WHERE CT.BUYER = A.BUYER AND CT.CODE1 = B.CATEGORY_NO AND CT.TYPE = 'CATE' AND CT.FLAG = 'Y') AS CATE_APPR , A.MG_NOTE , a.seq , A.DELY_TO_LOCATION_TEXT , A.RECV_USER_NAME , A.RECV_USER_TEL , A.ACCOUNT_TYPE AS CART_ACCOUNT_TYPE , C.DELIVERY_LT FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C ,ICOMCMPY CM, CMSCATLG D WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BUYER = #{buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{userid}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ||a.seq IN
#{item}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND A.BUYER = CM.COM_CODE AND B.STATUS <> 'D' AND C.STATUS <> 'D'
AND B.PRODUCT_CLOSE_FLAG IN ('N','Y')
AND B.PRODUCT_CLOSE_FLAG IN ('N','T')
AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND B.CMS_CATLG_ID = D.CMS_CATLG_ID(+) AND D.STD_FLAG(+)='Y' ) X, ICOMCMPY P WHERE X.AGENT = P.COM_CODE(+) GROUP BY X.IMGFILE_NAME, X.IMGFILE_DIR, X.BUYER_ITEM_NO, X.DESCRIPTION_LOC, X.SPECIFICATION, X.ORIGIN_NAME, X.MAKER_NAME, X.UNIT_MEASURE, X.TARGET_PRICE, X.CATEGORY_NO, P.COM_NAME_LOC, X.CART_QTY, X.TOT_SUM, X.STDCATEG_ID, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BYIT_COMORG_CODE, X.REF_PR_NO, X.AGENT, X.BDGT_FLAG, X.ACCOUNT_TYPE, X.IMAGE_KEY, X.CATE_APPR, X.MG_NOTE , x.seq , X.DELY_TO_LOCATION_TEXT , X.RECV_USER_NAME , X.RECV_USER_TEL , X.CART_ACCOUNT_TYPE , X.DELIVERY_LT ) Y ORDER BY Y.CART_SEQ, Y.BUYER_ITEM_NO ) Z

/*getBuyerShoppingCartOrderListConfirmList2_v2*/
SELECT ROWNUM No, --00 Z.IMGFILE_NAME, --01 Z.IMGFILE_DIR, --02 Z.BUYER_ITEM_NO, --03 Z.DESCRIPTION_LOC, --04 Z.SPECIFICATION, --05 Z.ORIGIN_NAME, --06 Z.MAKER_NAME, --07 Z.UNIT_MEASURE, --08 Z.TARGET_PRICE, --09 Z.CATEGORY_NO, --10 DECODE(NVL(Z.AGENT,'MULTI'),'MULTI','복수협력사입니다',Z.AGENT) AGENT, --11 Z.CART_QTY, --12 Z.TOT_SUM, --13 Z.STDCATEG_ID, --14 Z.CONTRACT_NO, --15 Z.CONTRACT_SEQ, --16 Z.BYIT_COMORG_CODE, --17 Z.REF_PR_NO, --18 Z.AGENT_CODE, --19 Z.BDGT_FLAG, --20 Z.ACCOUNT_TYPE --21 , Z.HI_DEPT_CODE --22 , Z.HI_DEPT_NAME --23 , Z.IMAGE_KEY , (SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO = Z.IMAGE_KEY) AS IMAGE_KEY_CNT , Z.CATE_APPR --25.카테고리별결재담당자 , Z.MG_NOTE , Z.CART_SEQ , Z.DELY_TO_LOCATION_TEXT , Z.DELY_TO_LOCATION , Z.DELY_TO_LOCATION_NAME||'('||Z.DELY_TO_LOCATION||')' AS DELY_TO_LOCATION_NAME , Z.RECV_USER_NAME , Z.RECV_USER_TEL , Z.CART_ACCOUNT_TYPE , F_GET_WORKINGDAY(TO_CHAR(SYSDATE, 'YYYYMMDD'), Z.DELIVERY_LT) AS DS_LT -- 표준납기일 , Z.DELIVERY_LT -- 납기 리드타임 , Z.BDGT_BAL_AMT , Z.BUDGET_DEPT , Z.REMARK , TO_CHAR(TO_DATE(Z.RD_DATE,'YYYYMMDD'),'YYYY-MM-DD') AS RD_DATE , Z.RD_DATE AS RD_DATE_ORG , Z.MNG_DEPT_NM , Z.ACCOUNT_NAME ,(SELECT COD.TEXT1 FROM ICOMCOD2 COD WHERE COD.TYPE = 'C001' AND COD.COMPANY_CODE = Z.BUYER AND COD.CODE = Z.BUDGET_DEPT) AS BUDGET_DEPT_NAME , Z.VIEW_FLAG FROM (SELECT ROWNUM NUM, Y.IMGFILE_NAME, Y.IMGFILE_DIR, Y.BUYER_ITEM_NO, Y.DESCRIPTION_LOC, Y.SPECIFICATION, Y.ORIGIN_NAME, Y.MAKER_NAME, Y.UNIT_MEASURE, Y.TARGET_PRICE, Y.CATEGORY_NO, Y.AGENT, Y.CART_QTY, Y.TOT_SUM, Y.STDCATEG_ID, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.BYIT_COMORG_CODE, Y.REF_PR_NO, Y.AGENT_CODE, Y.BDGT_FLAG, Y.ACCOUNT_TYPE, Y.HI_DEPT_CODE, Y.HI_DEPT_NAME, Y.IMAGE_KEY, Y.CATE_APPR, Y.MG_NOTE, Y.CART_SEQ, Y.DELY_TO_LOCATION_TEXT, Y.DELY_TO_LOCATION, Y.DELY_TO_LOCATION_NAME, Y.RECV_USER_NAME, Y.RECV_USER_TEL, Y.CART_ACCOUNT_TYPE, Y.DELIVERY_LT, Y.BDGT_BAL_AMT, Y.BUDGET_DEPT, Y.REMARK, Y.RD_DATE, Y.MNG_DEPT_NM, (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = Y.BUYER AND TYPE = 'Z014' AND CODE = DECODE(Y.CART_ACCOUNT_TYPE, NULL, DECODE(Y.P060000110_YN, 'Y', '', Y.CQDT_ACCOUNT_TYPE), Y.CART_ACCOUNT_TYPE)) AS ACCOUNT_NAME, Y.VIEW_FLAG, Y.BUYER FROM (SELECT X.IMGFILE_NAME, X.IMGFILE_DIR, MAX(X.BUYER_ITEM_NO) BUYER_ITEM_NO, X.DESCRIPTION_LOC, X.SPECIFICATION, X.ORIGIN_NAME, X.MAKER_NAME, X.UNIT_MEASURE, X.TARGET_PRICE, X.CATEGORY_NO, P.COM_NAME_LOC AGENT, X.CART_QTY, X.TOT_SUM, X.STDCATEG_ID, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BYIT_COMORG_CODE, X.REF_PR_NO, X.AGENT AGENT_CODE, X.BDGT_FLAG, X.ACCOUNT_TYPE, MAX(X.HI_DEPT_CODE) AS HI_DEPT_CODE, MAX(X.HI_DEPT_NAME) AS HI_DEPT_NAME, X.IMAGE_KEY, X.CATE_APPR, X.MG_NOTE, X.SEQ CART_SEQ, X.DELY_TO_LOCATION_TEXT, X.DELY_TO_LOCATION, X.DELY_TO_LOCATION_NAME, X.RECV_USER_NAME, X.RECV_USER_TEL, X.CART_ACCOUNT_TYPE, X.CQDT_ACCOUNT_TYPE, X.DELIVERY_LT, X.BDGT_BAL_AMT, X.BUDGET_DEPT, X.REMARK, X.RD_DATE, X.MNG_DEPT_NM, X.VIEW_FLAG, X.P060000110_YN, X.BUYER FROM ( SELECT DECODE(TRIM(B.IMGFILE_NAME), NULL, (SELECT IMG_NAME FROM CMSIMGES WHERE IMG_NO=D.IMG_NO),B.IMGFILE_NAME) AS IMGFILE_NAME, DECODE(TRIM(B.IMGFILE_DIR), NULL, (SELECT IMG_DIR FROM CMSIMGES WHERE IMG_NO=D.IMG_NO),B.IMGFILE_DIR) AS IMGFILE_DIR, C.BUYER_ITEM_NO, C.DESCRIPTION DESCRIPTION_LOC, C.SPECIFICATION, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE) ORIGIN_NAME, C.MAKER_NAME, C.UNIT_MEASURE, DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) TARGET_PRICE, B.CATEGORY_NO, DECODE(CM.AGENT_OPEN_FLAG,'Y',C.AGENT,'KRKORE0001') AGENT, DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) CART_QTY, (DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) ) TOT_SUM, B.STDCATEG_ID, C.CONTRACT_NO, C.CONTRACT_SEQ, A.BYIT_COMORG_CODE, A.REF_PR_NO, (SELECT Z.FLAG FROM ICOMCOD2 Z WHERE Z.TYPE = 'Z014' AND Z.COMPANY_CODE = A.BUYER AND Z.CODE = DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE,A.ACCOUNT_TYPE) ) BDGT_FLAG, A.ACCOUNT_TYPE ACCOUNT_TYPE ,A.BUDGET_DEPT , (SELECT NVL(PLAN_AMT, 0) - NVL(RESULT_AMT, 0) - NVL(TEMP_AMT, 0) FROM ICOMBDGT WHERE BUYER = A.BUYER AND DEPT = A.BUDGET_DEPT AND ACCOUNT_TYPE = A.ACCOUNT_TYPE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE) AS BDGT_BAL_AMT , A.HI_DEPT_CODE , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.HI_DEPT_CODE AND TYPE = 'U001' AND FLAG = 'Y') AS HI_DEPT_NAME , A.VERIF_NUM AS VERIF_NUM , A.IMAGE_KEY , (SELECT COUNT(*) FROM ICOMCOD3 CT WHERE CT.BUYER = A.BUYER AND CT.CODE1 = B.CATEGORY_NO AND CT.TYPE = 'CATE' AND CT.FLAG = 'Y') AS CATE_APPR , A.MG_NOTE , A.SEQ , A.DELY_TO_LOCATION_TEXT , A.DELY_TO_LOCATION , (SELECT COD2.TEXT1 FROM ICOMCOD2 COD2 WHERE COD2.TYPE = 'C012' AND COD2.COMPANY_CODE = A.BUYER AND COD2.CODE = A.DELY_TO_LOCATION AND COD2.FLAG = 'Y' ) AS DELY_TO_LOCATION_NAME , A.RECV_USER_NAME , A.RECV_USER_TEL , A.ACCOUNT_TYPE AS CART_ACCOUNT_TYPE , C.ACCOUNT_TYPE AS CQDT_ACCOUNT_TYPE , C.DELIVERY_LT , A.REMARK , A.RD_DATE , (SELECT TEXT2||'('||TEXT6||')' FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'Z014' AND CODE = DECODE(A.ACCOUNT_TYPE,NULL,C.ACCOUNT_TYPE,A.ACCOUNT_TYPE)) AS MNG_DEPT_NM , (SELECT DECODE(COUNT(A.SLG_ID), 0, 'N', 'Y') FROM BNTSLGDEF A, BNTSLGIMP B WHERE A.SLG_ID = B.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND B.COM_CODE = #{buyer} AND A.SLG_ID = 'P06-0000110') AS P060000110_YN ,A.BUYER , (SELECT VIEW_FLAG FROM ICOMBDGT WHERE BUYER = A.BUYER AND DEPT = A.BUDGET_DEPT AND ACCOUNT_TYPE = A.ACCOUNT_TYPE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE) AS VIEW_FLAG FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C ,ICOMCMPY CM, CMSCATLG D WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BUYER = #{buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{userid}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ||a.seq IN
#{item}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND A.BUYER = CM.COM_CODE AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N','T') AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND B.CMS_CATLG_ID = D.CMS_CATLG_ID(+) AND D.STD_FLAG(+)='Y' ) X, ICOMCMPY P WHERE X.AGENT = P.COM_CODE(+) GROUP BY X.IMGFILE_NAME, X.IMGFILE_DIR, X.BUYER_ITEM_NO, X.DESCRIPTION_LOC, X.SPECIFICATION, X.ORIGIN_NAME, X.MAKER_NAME, X.UNIT_MEASURE, X.TARGET_PRICE, X.REMARK, X.RD_DATE, X.CATEGORY_NO, P.COM_NAME_LOC, X.CART_QTY, X.TOT_SUM, X.STDCATEG_ID, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BYIT_COMORG_CODE, X.REF_PR_NO, X.AGENT, X.BDGT_FLAG, X.BUDGET_DEPT, X.BDGT_BAL_AMT, X.MNG_DEPT_NM, X.VIEW_FLAG, X.P060000110_YN, X.BUYER, X.ACCOUNT_TYPE, X.IMAGE_KEY, X.CATE_APPR, X.MG_NOTE , x.seq , X.DELY_TO_LOCATION_TEXT , X.DELY_TO_LOCATION_NAME , X.DELY_TO_LOCATION , X.RECV_USER_NAME , X.RECV_USER_TEL , X.CART_ACCOUNT_TYPE , X.CQDT_ACCOUNT_TYPE , X.DELIVERY_LT ) Y ORDER BY Y.DELY_TO_LOCATION,Y.DELY_TO_LOCATION_TEXT,Y.CART_SEQ, Y.BUYER_ITEM_NO ) Z

/*getOrderInfo_v2*/ SELECT DT.PR_NO ,DT.BUYER_ITEM_NO ,DT.DESCRIPTION AS DESCRIPTION_LOC ,DT.SPECIFICATION ,DT.TARGET_PRICE ,DT.TARGET_QTY ,(DT.TARGET_PRICE * DT.TARGET_QTY) AS TOT_PRICE ,DT.RECIPIENT_NAME AS RECV_USER_NAME ,DT.RECIPIENT_PHONE AS RECV_USER_TEL ,DT.DELY_TO_LOCATION_TEXT ,DT.DELY_TO_LOCATION ,(SELECT COD2.TEXT1||'('||COD2.CODE||')' FROM ICOMCOD2 COD2 WHERE COD2.TYPE = 'C012' AND COD2.COMPANY_CODE = DT.BUYER AND COD2.CODE = DT.DELY_TO_LOCATION AND COD2.FLAG = 'Y' ) AS DELY_TO_LOCATION_NAME ,HD.REMARK ,TO_CHAR(TO_DATE(DT.RD_DATE,'YYYYMMDD'),'YYYY-MM-DD') AS RD_DATE
,TO_CHAR(TO_DATE(POHD.PO_CREATE_DATE,'YYYYMMDD'),'YYYY-MM-DD') AS PRE_GR_DATE
,'' AS PRE_GR_DATE
,'' AS PRE_GR_DATE
FROM ICOMPRDT DT , ICOMPRHD HD
,ICOMPODT PODT , ICOMPOHD POHD WHERE DT.REF_NO = #{key_1} AND DT.BUYER = PODT.BUYER(+) AND DT.PR_NO = PODT.PR_NO(+) AND DT.PR_SEQ = PODT.PR_SEQ(+) AND PODT.BUYER = POHD.BUYER(+) AND PODT.PO_NO = POHD.PO_NO(+)
WHERE DT.REF_NO = #{key_1}
WHERE DT.PR_NO = #{key_1}
AND DT.BUYER = #{buyer} AND DT.STATUS != 'D' AND HD.STATUS != 'D' AND DT.BUYER = HD.BUYER AND DT.PR_NO = HD.PR_NO ORDER BY DT.DELY_TO_LOCATION,DT.BUYER_ITEM_NO



/*getPasslnInfo_v2*/

SELECT 
(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = PASSLN.USER_ID) AS USER_NAME
,PASS_TP
FROM ICOGPASSLN PASSLN
WHERE PASSLN.COMPANY = #{buyer}
AND PASSLN.DOCU_NO = #{docu_no}
ORDER BY ORDER_NO

/*selectCowayBuyerAdminBdgtTempCheck*/
SELECT (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.TYPE = 'Z014' AND C.COMPANY_CODE = X.BUYER AND C.CODE = X.ACCOUNT_TYPE ) ACCOUNT_TYPE_TEXT, -- 0 구분명 Z.MPAMT, -- 1 Y.RESULT_AMT, -- 2 Y.TEMP_AMT, -- 3 X.TOT_AMT, -- 4 DECODE(SIGN(Z.MPAMT - (Y.RESULT_AMT + Y.TEMP_AMT + X.TOT_AMT)),NULL,'예산미편성',-1 ,'예산초과','예산적용') BUYER_CHECK, -- 5 예산체크 X.BUDGET_DEPT , -- 6 X.ACCOUNT_TYPE, -- 7 (SELECT TEXT1 FROM ICOMCOD2 A WHERE A.COMPANY_CODE = X.BUYER AND A.CODE = X.BUDGET_DEPT AND A.TYPE = 'C001' ) AS BUDGET_DEPT_NAME -- 8 FROM (SELECT MAX(A.BUYER) BUYER, A.BUDGET_DEPT , A.ACCOUNT_TYPE, SUM((DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)))) TOT_AMT FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BUYER = #{buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{userid}
AND A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ||A.SEQ IN
#{item}
AND A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG = 'N' AND A.CONTRACT_NO = C.CONTRACT_NO AND B.ACCOUNT_TYPE = 'M' AND A.CONTRACT_SEQ = C.CONTRACT_SEQ GROUP BY A.BUDGET_DEPT , A.ACCOUNT_TYPE ) X , ICOMBDGT Y , COWAY_RESTS_ET_ORDER Z WHERE X.BUYER = Y.BUYER(+) AND X.BUDGET_DEPT = Y.DEPT(+) AND X.ACCOUNT_TYPE = Y.ACCOUNT_TYPE(+) AND X.BUDGET_DEPT = Z.AUFNR(+) AND X.ACCOUNT_TYPE = Z.BGACT(+) AND Z.GJAHR = TO_CHAR(SYSDATE,'YYYY') AND LPAD(Z.MONAT,2,'0') = TO_CHAR(SYSDATE,'MM') AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN Y.FROM_DATE(+) AND Y.TO_DATE(+)

/*selectBuyerAdminBdgtTempCheck*/
SELECT (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.TYPE = 'Z014' AND C.COMPANY_CODE = X.BUYER AND C.CODE = X.ACCOUNT_TYPE ) ACCOUNT_TYPE_TEXT, -- 0 구분명 Y.PLAN_AMT, -- 1 Y.RESULT_AMT, -- 2 Y.TEMP_AMT, -- 3 X.TOT_AMT, -- 4 DECODE(SIGN(Y.PLAN_AMT - (Y.RESULT_AMT + Y.TEMP_AMT + X.TOT_AMT)),NULL,'예산미편성',-1 ,'예산초과','예산적용') BUYER_CHECK, -- 5 예산체크 X.BUDGET_DEPT , -- 6 X.ACCOUNT_TYPE, -- 7 (SELECT TEXT1 FROM ICOMCOD2 A WHERE A.COMPANY_CODE = X.BUYER AND A.CODE = X.BUDGET_DEPT AND A.TYPE = 'C001' ) AS BUDGET_DEPT_NAME -- 8 FROM (SELECT MAX(A.BUYER) BUYER, A.BUDGET_DEPT , A.ACCOUNT_TYPE, SUM((DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)))) TOT_AMT FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BUYER = #{buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{userid}
AND A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ||A.SEQ IN
#{item}
AND A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG = 'N' AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND NVL((SELECT NVL(FLAG,'N') FROM icomcod2 WHERE company_code = A.BUYER AND TYPE = 'Z014' AND CODE = A.ACCOUNT_TYPE),'N') = 'Y' GROUP BY A.BUDGET_DEPT , A.ACCOUNT_TYPE ) X , ICOMBDGT Y WHERE X.BUYER = Y.BUYER(+) AND X.BUDGET_DEPT = Y.DEPT(+) AND X.ACCOUNT_TYPE = Y.ACCOUNT_TYPE(+) AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN Y.FROM_DATE(+) AND Y.TO_DATE(+)

