/*select_buyer_admin_bdgt_temp_order_check */ SELECT (SELECT C.TEXT2 FROM ICOMCOD2 C WHERE C.TYPE = 'Z014' AND C.COMPANY_CODE = X.BUYER AND C.CODE = X.ACCOUNT_TYPE ) 구분명, -- 0 Y.PLAN_AMT, -- 1 Y.RESULT_AMT, -- 2 Y.TEMP_AMT, -- 3 X.TOT_AMT, -- 4 DECODE(SIGN(Y.PLAN_AMT - (Y.RESULT_AMT + Y.TEMP_AMT + X.TOT_AMT)), -1 ,'예산초과','예산적용') 예산체크, -- 5 X.BUDGET_DEPT , -- 6 X.ACCOUNT_TYPE, -- 7 (SELECT TEXT1 FROM ICOMCOD2 A WHERE A.COMPANY_CODE = X.BUYER AND A.CODE = X.BUDGET_DEPT AND A.TYPE = 'C001' ) AS BUDGET_DEPT_NAME -- 8 FROM (SELECT MAX(A.BUYER) BUYER, A.BUDGET_DEPT , A.ACCOUNT_TYPE,
SUM(( DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1))) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.TARGET_PRICE,0),NVL(C.UNIT_PRICE,0))) TOT_AMT -- 재구매요청 , 재발주 경우 ==> 요청반려(RR) , 요청결재반려(GR) , 발주결재반려(PR)
SUM((DECODE(A.RECV_QTY,0,1,NVL(A.RECV_QTY,1))-A.TARGET_QTY * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.TARGET_PRICE,0),NVL(C.UNIT_PRICE,0)))) TOT_AMT -- 요청접수발주 , 발주보류
FROM ICOMPRDT A, ICOMBYIT B, ICOMCQDT C WHERE A.BUYER = #{BUYER}
AND A.PR_NO||A.PR_SEQ IN
#{item}
AND A.BYIT_COMORG_CODE = B.BUYER AND B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG = 'N' AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ GROUP BY A.BUDGET_DEPT , A.ACCOUNT_TYPE ) X , ICOMBDGT Y WHERE X.BUYER = Y.BUYER AND X.BUDGET_DEPT = Y.DEPT AND X.ACCOUNT_TYPE = Y.ACCOUNT_TYPE AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN Y.FROM_DATE AND Y.TO_DATE

