INSERT INTO ICOMPRDT ( BUYER, PR_NO, PR_SEQ, STATUS, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, BUYER_ITEM_NO, SELLER_ITEM_NO, SELLER, CATALOG_ITEM_NO, ITEM_TYPE, DESCRIPTION, SPECIFICATION, HS_NO, MAKER_CODE, MAKER_NAME, MAKER_PART_NO, IMAGE_KEY, UNIT_MEASURE, CUR, RD_DATE, TARGET_PRICE, TARGET_QTY, DELY_TO_LOCATION, ACCOUNT_TYPE, RECV_FLAG, PURCHASING_AGENT_FLAG, PO_QTY, RETURN_REASON, REMARK, RFQ_NO, RFQ_COUNT, RFQ_SEQ, SAMPLE_FLAG, COMPLETE_MARK, RECV_QTY, GR_QTY, CTR_QTY, PURCHASER_ID, SUB_PURCHASER_ID, PURCHASER_DEPT, SAVE_FLAG, ADD_USER_ID, ADD_USER_NAME, ADD_USER_TEL, ADD_USER_DEPT, CHANGE_USER_ID, CHANGE_USER_NAME, CHANGE_USER_TEL, CHANGE_USER_DEPT, REF_NO, REF_SEQ, REF_PR_NO, REF_ADD_USER_ID, REQ_USER_ID, REQ_DEPT, AGENT, CONTRACT_NO, CONTRACT_SEQ, LEGACY_PO_NO, LEGACY_PO_SEQ, REF_IF_NO, LIST_PRICE, DOC_TYPE, REQ_USER_INFO, PLAN_AMT_FLAG, BYIT_COMORG_CODE, PROCESS_TYPE, CATEG_ID )
( SELECT PR.BUYER, -- BUYER #{NEW_PR_NO}, -- 1 PR_NO TO_CHAR(#{PR_SEQ},'FM000000'), -- 2 PR_SEQ 'C', -- STATUS TO_CHAR(SYSDATE,'YYYYMMDD'), -- ADD_DATE TO_CHAR(SYSDATE,'HH24MISS'), -- ADD_TIME TO_CHAR(SYSDATE,'YYYYMMDD'), -- CHANGE_DATE TO_CHAR(SYSDATE,'HH24MISS'), -- CHANGE_TIME CQ.BUYER_ITEM_NO, -- BUYER_ITEM_NO CQ.SELLER_ITEM_NO, -- SELLER_ITEM_NO CQ.SELLER, -- SELLER CQ.CATALOG_ITEM_NO, -- CATALOG_ITEM_NO CQ.ITEM_TYPE, -- ITEM_TYPE CQ.DESCRIPTION, -- DESCRIPTION CQ.SPECIFICATION, -- SPECIFICATION CQ.HS_NO, -- HS_NO CQ.MAKER_CODE, -- MAKER_CODE CQ.MAKER_NAME, -- MAKER_NAME CQ.MAKER_PART_NO, -- MAKER_PART_NO '', -- IMAGE_KEY CQ.UNIT_MEASURE, -- UNIT_MEASURE CQ.CUR, -- CUR #{RD_DATE}, -- 3 RD_DATE CQ.TARGET_PRICE, -- TARGET_PRICE #{TARGET_QTY}, -- 4 TARGET_QTY '', -- DELY_TO_LOCATION CQ.ACCOUNT_TYPE, -- ACCOUNT_TYPE #{RECV_FLAG}, -- 5 RECV_FLAG 'N', -- PURCHASING_AGENT_FLAG 0, -- PO_QTY '' , -- RETURN_REASON '' , -- REMARK '' , -- RFQ_NO '' , -- RFQ_COUNT '' , -- RFQ_SEQ 'N', -- SAMPLE_FLAG '' , -- COMPLETE_MARK 0, -- RECV_QTY 0, -- GR_QTY 0, -- CTR_QTY '', -- PURCHASER_ID '', -- SUB_PURCHASER_ID PR.PURCHASER_DEPT, -- PURCHASER_DEPT 'PR', -- SAVE_FLAG PR.ADD_USER_ID, -- ADD_USER_ID PR.ADD_USER_NAME, -- ADD_USER_NAME PR.ADD_USER_TEL, -- ADD_USER_TEL PR.ADD_USER_DEPT, -- ADD_USER_DEPT PR.CHANGE_USER_ID, -- CHANGE_USER_ID PR.CHANGE_USER_NAME, -- CHANGE_USER_NAME PR.CHANGE_USER_TEL, -- CHANGE_USER_TEL PR.CHANGE_USER_DEPT, -- CHANGE_USER_DEPT '', -- REF_NO '', -- REF_SEQ PR.REF_PR_NO, -- REF_PR_NO '' , -- PR.REF_ADD_USER_ID PR.REQ_USER_ID , -- PR.REQ_USER_ID PR.REQ_DEPT , -- PR.REQ_DEPT CQ.AGENT, -- AGENT CQ.CONTRACT_NO, -- CONTRACT_NO CQ.CONTRACT_SEQ, -- CONTRACT_SEQ '', -- LEGACY_PO_NO '', -- LEGACY_PO_SEQ '', -- REF_IF_NO CQ.LIST_PRICE, -- LIST_PRICE '', -- DOC_TYPE '', -- REQ_USER_INFO (SELECT C.FLAG FROM ICOMCOD2 C WHERE C.TYPE = 'Z014' AND C.COMPANY_CODE = PR.BUYER AND C.CODE = CQ.ACCOUNT_TYPE) PLAN_AMT_FLAG, -- PLAN_AMT_FLAG PR.BYIT_COMORG_CODE, -- BYIT_COMORG_CODE CQ.PROCESS_TYPE, -- PROCESS_TYPE BT.CATEGORY_NO CATEG_ID -- CATEG_ID FROM ICOMPRDT PR , ICOMCQDT CQ, ICOMBYIT BT WHERE PR.BUYER = #{BUYER} -- 6 AND PR.PR_NO = #{PR_NO} -- 7 AND PR.PR_SEQ = #{PR_SEQ} -- 8 AND PR.BYIT_COMORG_CODE = BT.BUYER AND PR.BUYER_ITEM_NO = BT.BUYER_ITEM_NO AND CQ.BUYER = BT.BUYER AND CQ.BUYER_ITEM_NO = BT.BUYER_ITEM_NO AND PR.BUYER_ITEM_NO = CQ.BUYER_ITEM_NO AND PR.CONTRACT_NO = CQ.CONTRACT_NO AND PR.CONTRACT_SEQ = CQ.CONTRACT_SEQ AND PR.AGENT = CQ.AGENT AND BT.PRODUCT_CLOSE_FLAG = 'N' AND BT.STATUS <> 'D' AND CQ.STATUS <> 'D' )

/*buyer_new_recreate_order_ICOMPRHD*/
INSERT INTO ICOMPRHD ( BUYER, PR_NO, STATUS, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, NOTIFY, PR_SUBJECT, PURCHASER_DEPT, RECV_FLAG, RETURN_REASON, ACCOUNT_TYPE, INVESTMENT_NO, SAMPLE_FLAG, DELY_TO_LOCATION, REMARK, ADD_USER_ID, ADD_USER_NAME, ADD_USER_TEL, ADD_USER_DEPT, CHANGE_USER_ID, CHANGE_USER_NAME, CHANGE_USER_TEL, CHANGE_USER_DEPT, SIGN_DATE, SIGN_PERSON_ID, SAVE_FLAG, IMAGE_KEY, DOC_TYPE )
( SELECT PRDT.BUYER BUYER, #{NEW_PR_NO} PR_NO, -- 1 'C' STATUS, TO_CHAR(SYSDATE,'YYYYMMDD') ADD_DATE, TO_CHAR(SYSDATE,'HH24MISS') ADD_TIME, TO_CHAR(SYSDATE,'YYYYMMDD') CHANGE_DATE, TO_CHAR(SYSDATE,'HH24MISS') CHANGE_TIME, PRDT.BUYER NOTIFY, '*' PR_SUBJECT, PURCHASER_DEPT PURCHASER_DEPT, -- 2 #{RECV_FLAG} RECV_FLAG, -- 3 '' RETURN_REASON, PRDT.ACCOUNT_TYPE ACCOUNT_TYPE, '*' INVESTMENT_NO, 'N' SAMPLE_FLAG, #{DELY_TO_LOCATION} DELY_TO_LOCATION, -- 4 #{REMARK} REMARK, -- 5 PRDT.ADD_USER_ID ADD_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID) ADD_USER_NAME, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID) ADD_USER_TEL, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID) ADD_USER_DEPT, PRDT.ADD_USER_ID CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID) CHANGE_USER_NAME, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID) CHANGE_USER_TEL, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID) CHANGE_USER_DEPT, '' SIGN_DATE, '' SIGN_PERSON_ID, 'PR' SAVE_FLAG, '' IMAGE_KEY, #{DOC_TYPE} DOC_TYPE -- 6 FROM ICOMPRDT PRDT WHERE BUYER = #{BUYER} -- 7 AND PR_NO = #{PR_NO} -- 8 AND PR_SEQ = '000001' )



	/*buyer_new_recreate_order_getTempBdgtUpdate*/

               UPDATE ICOMBDGT A SET																
                          A.TEMP_AMT = A.TEMP_AMT +  #{END_PRICE}	 
                  WHERE A.BUYER =#{BUYER}	 		
                    AND A.DEPT =#{DEPT}	 					
                    AND A.ACCOUNT_TYPE =#{ACCOUNT_TYPE}	 
                    AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN A.FROM_DATE AND A.TO_DATE



			  /*ICOMPRHD_TRG2*/

	                    UPDATE IF_PROGRESS
                            SET IF_FLAG = 'Z',
                                CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
                                CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS'),
                                ERR_MSG     = '?????!!'
                         WHERE BUYER = #{BUYER} 
                          AND  LEGACY_NO = #{PR_NO} 
                          AND  GUBUN     = 'XX'
                          AND  REVISION  = '00'

mapper.select:


	   /* get_sms_ICOMTRXL*/

      SELECT COUNT(*)
          V_CNT
        FROM ICOMTRXL
       WHERE DOC_NAME = #{DOC_NAME}
         AND TARGET = #{TARGET} 
         AND KEY_1  =  #{KEY_1}
         AND KEY_2  = #{KEY_2} 
         AND KEY_3  = #{KEY_3} 
         AND KEY_4  = #{KEY_4} 
         AND KEY_5  = #{KEY_5} 
         AND KEY_6  = #{KEY_6} 
         AND KEY_7  = #{KEY_7} 
         AND KEY_8  = #{KEY_8} 
         AND KEY_9  = #{KEY_9} 
         AND KEY_10 = #{KEY_10} 
         AND ROWNUM = 1



   /* MAIL_PODT_TRG1*/

	SELECT COUNT(*)
	  V_CNT
	FROM ICOMPOHD
	WHERE BUYER = #{BUYER} 
	AND   PO_NO = #{PO_NO} 
	AND   DOC_TYPE = 'X'



	   /* MAIL_PODT_TRG4*/

		SELECT COUNT(*)
               V_DEL_CNT
           FROM   ICOMPRDT
           WHERE  BUYER = #{BUYER} 
           AND    PR_NO = #{PR_NO} 
           AND    PR_SEQ= #{PR_SEQ} 
           AND    STATUS ^= 'D'



	   /* MAIL_PODT_TRG6*/

        SELECT MAX(AGENT)   V_AGENT
          FROM ICOMPOHD
         WHERE BUYER =#{BUYER} AND PO_NO = #{PO_NO}



	   /* MAIL_PODT_TRG8*/


        SELECT MAX(A.AGENT) V_AGENT, MAX(B.ADD_USER_ID)  V_SEND_USER_ID
          FROM ICOMPOHD A, ICOMPORS B
         WHERE A.BUYER =  #{BUYER} AND A.PO_NO =  #{PO_NO}
           AND A.BUYER = B.BUYER    AND A.PO_NO = B.PO_NO



	   /* get_MAILSEND_LIKE*/

		SELECT COUNT(*)
		  V_CNT
             FROM MAILSEND
            WHERE MAILFORM_ID   LIKE  #{MAILFORM_ID} || '%'
              AND SEND_COM_CODE = #{BUYER} 
              AND SEND_USER_ID  = #{SEND_USER_ID} 
              AND KEY1          = #{KEY1} 
              AND KEY2          = #{KEY2} 
              AND ROWNUM = 1



	   /* get_MAILSEND_EQUALS*/

		SELECT COUNT(*)
		  V_CNT
             FROM MAILSEND
            WHERE MAILFORM_ID   =  #{MAILFORM_ID} 
              AND SEND_COM_CODE = #{BUYER} 
              AND SEND_USER_ID  = #{SEND_USER_ID} 
              AND KEY1          = #{KEY1} 
              AND KEY2          = #{KEY2} 
              AND ROWNUM = 1



	   /* get_MAILSEND_ICOMPRDT*/

           SELECT COUNT(*)
               V_DEL_CNT
           FROM   ICOMPRDT
           WHERE  BUYER = #{BUYER} 
           AND    PR_NO = #{PR_NO} 
           AND    PR_SEQ= #{PR_SEQ} 
           AND    STATUS ^= 'D';


/* buyer.mpso.getCowayMgcodeList */
SELECT SUM (MG_CODE) MG_CODE
     , NVL (SUM (A.TARGET_PRICE * A.TARGET_QTY), 0) PR_AMT
     , DECODE (SUM (MG_CODE), NVL (SUM (A.TARGET_PRICE * A.TARGET_QTY), 0), 'O',  'X') CLS
  FROM ICOMPRDT A
 WHERE A.STATUS <> 'D' 
   AND A.MG_CODE IS NOT NULL 
   AND A.BUYER = #{BUYER } 
   AND A.PR_NO= #{PR_NO }

