INSERT INTO COWAY_POINT_HISTORY
	(BUYER, PR_NO, PR_SEQ, BUYER_ITEM_NO, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, POINT_AMT)
SELECT BUYER, PR_NO, PR_SEQ, BUYER_ITEM_NO, TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), DECODE(#{CANCEL_FLAG }, 'Y', MG_CODE*-1, MG_CODE)
  FROM ICOMPRDT
 WHERE BUYER= #{BUYER } 
   AND PR_NO= #{PR_NO }

