/*buyer.mpso.selectLtalAppInfo*/ SELECT K.*, MAX( CASE WHEN K.RANK = 1 THEN DESCRIPTION ELSE '' END) OVER () || CASE WHEN CNT != 1 THEN ' 외 ' || TO_CHAR(K.CNT - 1) || '건' ELSE '' END AS SUBJECT FROM ( SELECT A.BUYER, A.PR_NO, A.PR_SEQ, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND CODE = A.ADD_USER_DEPT AND COMPANY_CODE = A.BUYER) AS PURCHASE_DEPT, ' ' AS ITEM_TYPE, A.ADD_DATE AS PO_CREATE_DATE, (SELECT TEXT4 FROM ICOMCOD2 WHERE TYPE = 'C002' AND CODE = A.BUYER AND COMPANY_CODE = C.BYCA_COMORG_CODE) AS PLANT, ' ' AS LOCATION, NVL(B.REMARK, ' ') AS HD_REMARK, COUNT(*) OVER (PARTITION BY A.BUYER, A.PR_NO) AS PO_CNT, SUM(A.TARGET_QTY) OVER (PARTITION BY A.BUYER, A.PR_NO) AS ITEM_QTY_SUM, SUM(A.TARGET_QTY * A.TARGET_PRICE) OVER (PARTITION BY A.BUYER, A.PR_NO) AS ITEM_AMT_SUM, A.BUYER_ITEM_NO, A.DESCRIPTION, A.SPECIFICATION, A.UNIT_MEASURE, A.TARGET_QTY AS ITEM_QTY, A.TARGET_PRICE AS UNIT_PRICE, (A.TARGET_QTY * A.TARGET_PRICE) AS ITEM_AMT, A.MAKER_NAME, NVL(D.ORIGIN_CODE, ' ') AS ORIGIN_NAME, NVL(A.PO_REMARK, ' ') AS PO_REMARK, ROW_NUMBER() OVER (ORDER BY A.BUYER, A.PR_NO, A.PR_SEQ) AS RANK, COUNT(*) OVER () AS CNT FROM ICOMPRDT A , ICOMPRHD B , ICOMCMPY C , ICOMBYIT D WHERE A.BUYER = #{BUYER} AND A.PR_NO = #{PR_NO}
AND B.BUYER = A.BUYER AND B.PR_NO = A.PR_NO
AND C.COM_CODE = A.BUYER
AND D.BUYER = C.BYCA_COMORG_CODE AND D.BUYER_ITEM_NO = A.BUYER_ITEM_NO ORDER BY A.BUYER, A.PR_NO, A.PR_SEQ ) K

/*"selectICOMCARTStockCheck"*/ SELECT COUNT(X.KEY_1) AS CNT FROM ( SELECT A.BYIT_COMORG_CODE||A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ AS KEY_1 , SUM(A.CART_QTY) AS CART_QTY , MAX(B.VALUE1) AS VALUE1 FROM ICOMCART A, ICOMCOD2 B WHERE B.TYPE ='WMST' AND A.BUYER = B.COMPANY_CODE AND A.BYIT_COMORG_CODE||A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ = B.CODE AND B.FLAG = 'Y' AND A.BUYER = #{buyer } AND A.USER_ID = #{userid }
AND A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ||A.SEQ IN
#{item}
AND A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ IN
#{item}
GROUP BY A.BYIT_COMORG_CODE||A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ ) X WHERE X.CART_QTY > X.VALUE1

